import json, pathlib, hashlib, zlib, base64
src=pathlib.Path('.lab/fixtures/qidu-day-gate/Qidu-v0.4.45-morning-lore-correct.json')
dst=pathlib.Path('.lab/fixtures/qidu-day-gate/Qidu-v0.4.46-node1-guard-fix.json')
card=json.loads(src.read_text(encoding='utf-8'))
guard=next(s for s in card['data']['extensions']['tavern_helper']['scripts'] if s.get('name')=='七都｜MVU不可逆结算守卫')
guard['content']=zlib.decompress(base64.b64decode('')).decode('utf-8')
card['character_version']='0.4.46-node1-guard-fix'
card['data']['character_version']='0.4.46-node1-guard-fix'
dst.write_text(json.dumps(card,ensure_ascii=False,indent=2),encoding='utf-8')
sha=hashlib.sha256(dst.read_bytes()).hexdigest()
expected='cf9b124a60b2e14027548616d69eb315819143b1aec36865e49d9bd1e877b76a'
if sha!=expected: raise RuntimeError(f'candidate hash mismatch: {sha} != {expected}')
print(f'node1 candidate ready: {dst} sha256={sha}')
